To implement the validation function, you could create a method within `src/flagService.js`. Here’s a sample function to check for uniqueness and format:

```javascript
const existingFlags = [];

function validateFlag(flag) {
    const flagFormat = /^[A-Z_]+$/;
    if (!flagFormat.test(flag)) {
        throw new Error('Flag must be in uppercase and use underscores.');
    }
    if (existingFlags.includes(flag)) {
        throw new Error('Flag must be unique.');
    }
    existingFlags.push(flag);
}

module.exports = { validateFlag };
```

Also, remember to write corresponding tests in `tests/flagService.test.js`. You can use Jest to test this implementation:

```javascript
const { validateFlag } = require('../src/flagService');

describe('validateFlag', () => {
    it('should throw an error if the flag format is invalid', () => {
        expect(() => validateFlag('invalid-flag')).toThrow('Flag must be in uppercase and use underscores.');
    });
    it('should throw an error if the flag is not unique', () => {
        validateFlag('UNIQUE_FLAG');
        expect(() => validateFlag('UNIQUE_FLAG')).toThrow('Flag must be unique.');
    });
    it('should add the flag to existingFlags if valid', () => {
        validateFlag('ANOTHER_FLAG');
        expect(() => validateFlag('ANOTHER_FLAG')).not.toThrow();
    });
});
```

Finally, update your `config/flagConfig.json` to include any additional flag constraints if necessary.
